// Build an AI image generation prompt based on the topic
const topic = $json.topic;
const prompt = encodeURIComponent(`Professional digital illustration of ${topic}, futuristic technology concept, clean modern design, blue and purple gradient, minimalist style`);
const imageUrl = `https://image.pollinations.ai/prompt/${prompt}?width=1200&height=628&nologo=true`;

return {
  json: {
    imageUrl: imageUrl,
    topic: $json.topic,
    postText: $json.postText
  }
};

// Pass through the AI-generated image URL from Pollinations
const imageUrl = $input.first().json.imageUrl;
const postText = $input.first().json.postText || $('Set Post Content').item.json.postText;
const topic = $input.first().json.topic || $('Set Post Content').item.json.topic;

return {
  json: {
    imageUrl: imageUrl,
    imageDescription: `AI-generated illustration for ${topic}`,
    photographer: 'Pollinations AI (free, no API key required)',
    photographerLink: 'https://pollinations.ai',
    postText: postText,
    topic: topic
  }
};

